  1	// Debate config (Kaizen v0): `--config debate.yaml` selects the participant
  2	// lineup so each run can choose adapters that match the target repository policy.
  3	//
  4	// This parses a deliberately MINIMAL YAML subset — flat top-level scalars plus
  5	// one `participants:` list of flat maps — with strict, line-numbered errors.
  6	// No dependency, no build step (the repo's standing rule). When config needs
  7	// real YAML (nesting, anchors), switch to a parser library; do not grow this.
  8	
  9	export type AdapterId = "claude" | "agy" | "codex" | "pi" | "copilot-cli";
 10	
 11	export type ParticipantSpec = {
 12	  adapter: AdapterId;
 13	  model?: string;        // omit = the adapter's default (codex: the account default)
 14	  bin?: string;          // override the binary path (e.g. a shadowed codex install)
 15	  maxBudgetUsd?: number; // claude only
 16	  effort?: string;       // reasoning effort, to dose token spend. claude: --effort
 17	                         // (low|medium|high|xhigh|max); codex: model_reasoning_effort
 18	                         // (minimal|low|medium|high). NOT supported by agy (effort is
 19	                         // baked into the model name, e.g. "Gemini 3.5 Flash (High)").
 20	                         // Free-form string: the CLI validates it (errors surface in
 21	                         // the raw capture / --doctor), so this parser stays version-agnostic.
 22	};
 23	
 24	export type DebateConfig = {
 25	  rounds?: number;
 26	  repo?: string;
 27	  timeoutMinutes?: number;
 28	  participants?: ParticipantSpec[];
 29	  judge?: ParticipantSpec; // the respondeo agent: renders the consolidatio (opt-in)
 30	};
 31	
 32	// The inverse of parseDebateConfig: emit the same minimal YAML subset this module
 33	// parses, so a generated config round-trips back through parseDebateConfig unchanged.
 34	// Used by `disputatio --init` to write ~/.config/disputatio/config.yaml. Keep it in
 35	// lock-step with the parser — if one grows a key, so must the other (round-trip test).
 36	const PARTICIPANT_ORDER: (keyof ParticipantSpec)[] = ["adapter", "model", "bin", "maxBudgetUsd", "effort"];
 37	
 38	// Quote a scalar only when leaving it bare would change how the parser reads it — namely
 39	// edge whitespace or an empty value (both eaten by the parser otherwise). Plain values
 40	// like model names with spaces/parens ("Gemini 3.5 Flash (High)") stay unquoted; the
 41	// parser reads the whole rest-of-line. A value with a `(^|\s)#` is UNREPRESENTABLE — the
 42	// parser strips trailing comments before handling quotes, so quoting can't save it; we
 43	// refuse it loudly rather than write config that silently round-trips to something else.
 44	function emitScalar(v: string | number): string {
 45	  if (typeof v === "number") return String(v);
 46	  if (/(^|\s)#/.test(v)) throw new Error(`config value cannot contain a "#" comment marker: ${JSON.stringify(v)}`);
 47	  return v === "" || v !== v.trim() ? JSON.stringify(v) : v;
 48	}
 49	
 50	function emitSpec(spec: ParticipantSpec, indent: string, firstPrefix: string): string {
 51	  const lines: string[] = [];
 52	  let prefix = firstPrefix;
 53	  for (const key of PARTICIPANT_ORDER) {
 54	    const val = spec[key];
 55	    if (val === undefined) continue;
 56	    lines.push(`${prefix}${key}: ${emitScalar(val)}`);
 57	    prefix = indent; // only the first key carries the "- " list marker
 58	  }
 59	  return lines.join("\n");
 60	}
 61	
 62	export function serializeDebateConfig(cfg: DebateConfig): string {
 63	  const out: string[] = [];
 64	  if (cfg.rounds !== undefined) out.push(`rounds: ${cfg.rounds}`);
 65	  if (cfg.timeoutMinutes !== undefined) out.push(`timeoutMinutes: ${cfg.timeoutMinutes}`);
 66	  if (cfg.repo !== undefined) out.push(`repo: ${emitScalar(cfg.repo)}`);
 67	  if (cfg.participants) {
 68	    out.push("participants:");
 69	    for (const p of cfg.participants) out.push(emitSpec(p, "    ", "  - "));
 70	  }
 71	  if (cfg.judge) {
 72	    out.push("judge:");
 73	    out.push(emitSpec(cfg.judge, "  ", "  "));
 74	  }
 75	  return out.join("\n") + "\n";
 76	}
 77	
 78	const ADAPTERS = new Set<string>(["claude", "agy", "codex", "pi", "copilot-cli"]);
 79	const TOP_KEYS = new Set<string>(["rounds", "repo", "timeoutMinutes", "participants", "judge"]);
 80	const PARTICIPANT_KEYS = new Set<string>(["adapter", "model", "bin", "maxBudgetUsd", "effort"]);
 81	const NUMERIC_KEYS = new Set<string>(["rounds", "timeoutMinutes", "maxBudgetUsd"]);
 82	
 83	function fail(lineNo: number, msg: string): never {
 84	  throw new Error(`debate config line ${lineNo}: ${msg}`);
 85	}
 86	
 87	function scalar(raw: string, key: string, lineNo: number): string | number {
 88	  let v = raw.trim();
 89	  const quoted = (v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"));
 90	  if (quoted) v = v.slice(1, -1);
 91	  if (v === "") fail(lineNo, `key "${key}" has no value`);
 92	  if (NUMERIC_KEYS.has(key)) {
 93	    const n = Number(v);
 94	    if (!Number.isFinite(n)) fail(lineNo, `key "${key}" must be a number, got "${v}"`);
 95	    return n;
 96	  }
 97	  return v;
 98	}
 99	
100	export function parseDebateConfig(text: string): DebateConfig {
101	  const cfg: DebateConfig = {};
102	  let participants: Record<string, string | number>[] | null = null;
103	  // The judge is a single spec (not a list). The `in*` flags track which block's
104	  // continuation lines we are currently reading; any new top-level key closes both
105	  // (so the accumulators are NOT discarded — a later `judge:` must not drop the
106	  // already-parsed participants, nor a later top key the judge).
107	  let judge: Record<string, string | number> | null = null;
108	  let inParticipants = false;
109	  let inJudge = false;
110	
111	  const lines = text.split("\n");
112	  for (let i = 0; i < lines.length; i++) {
113	    const lineNo = i + 1;
114	    const noComment = lines[i].replace(/(^|\s)#.*$/, ""); // strip full-line & trailing comments
115	    if (noComment.trim() === "") continue;
116	
117	    const top = noComment.match(/^([A-Za-z][A-Za-z0-9]*):\s*(.*)$/);          // key: value (indent 0)
118	    const item = noComment.match(/^\s+-\s+([A-Za-z][A-Za-z0-9]*):\s*(.*)$/);  //   - key: value
119	    const cont = noComment.match(/^\s+([A-Za-z][A-Za-z0-9]*):\s*(.*)$/);      //     key: value
120	
121	    if (top) {
122	      const [, key, rest] = top;
123	      if (!TOP_KEYS.has(key)) fail(lineNo, `unknown key "${key}" (known: ${[...TOP_KEYS].join(", ")})`);
124	      // A new top-level key always ends the current block (but keeps its accumulator).
125	      inParticipants = key === "participants";
126	      inJudge = key === "judge";
127	      if (key === "participants") {
128	        if (rest.trim() !== "") fail(lineNo, `"participants" must be a list (put items on the following lines)`);
129	        participants = [];
130	      } else if (key === "judge") {
131	        if (rest.trim() !== "") fail(lineNo, `"judge" must be a block (put its keys on the following indented lines)`);
132	        judge = {};
133	      } else {
134	        (cfg as Record<string, unknown>)[key] = scalar(rest, key, lineNo);
135	      }
136	    } else if (item && inParticipants && participants) {
137	      const [, key, rest] = item;
138	      if (!PARTICIPANT_KEYS.has(key)) fail(lineNo, `unknown participant key "${key}" (known: ${[...PARTICIPANT_KEYS].join(", ")})`);
139	      participants.push({ [key]: scalar(rest, key, lineNo) });
140	    } else if (cont && inParticipants && participants) {
141	      const [, key, rest] = cont;
142	      if (!PARTICIPANT_KEYS.has(key)) fail(lineNo, `unknown participant key "${key}" (known: ${[...PARTICIPANT_KEYS].join(", ")})`);
143	      const current = participants[participants.length - 1];
144	      if (!current) fail(lineNo, `participant field before any "- " list item`);
145	      if (key in current) fail(lineNo, `duplicate participant key "${key}"`);
146	      current[key] = scalar(rest, key, lineNo);
147	    } else if (cont && inJudge && judge) {
148	      const [, key, rest] = cont;
149	      if (!PARTICIPANT_KEYS.has(key)) fail(lineNo, `unknown participant key "${key}" (known: ${[...PARTICIPANT_KEYS].join(", ")})`);
150	      if (key in judge) fail(lineNo, `duplicate judge key "${key}"`);
151	      judge[key] = scalar(rest, key, lineNo);
152	    } else {
153	      fail(lineNo, `cannot parse "${lines[i].trim()}" (this parser supports only flat "key: value" and a participants list)`);
154	    }
155	  }
156	
157	  if (participants) {
158	    for (const p of participants) {
159	      if (typeof p.adapter !== "string" || !ADAPTERS.has(p.adapter)) {
160	        throw new Error(`debate config: each participant needs "adapter: claude | agy | codex | pi | copilot-cli" (got ${JSON.stringify(p)})`);
161	      }
162	    }
163	    if (participants.length < 2) {
164	      throw new Error(`debate config: a debate needs at least 2 participants (got ${participants.length})`);
165	    }
166	    cfg.participants = participants as ParticipantSpec[];
167	  }
168	  if (judge) {
169	    if (typeof judge.adapter !== "string" || !ADAPTERS.has(judge.adapter)) {
170	      throw new Error(`debate config: the judge needs "adapter: claude | agy | codex | pi | copilot-cli" (got ${JSON.stringify(judge)})`);
171	    }
172	    cfg.judge = judge as ParticipantSpec;
173	  }
174	  if (cfg.rounds !== undefined && (!Number.isInteger(cfg.rounds) || cfg.rounds < 0)) {
175	    throw new Error(`debate config: "rounds" must be a non-negative integer`);
176	  }
177	  return cfg;
178	}

