  1	// Transport layer (Kaizen v0).
  2	// One job: spawn a real agent CLI, capture its output, classify success/failure.
  3	// Every rule here is grounded in research/canary-results.md (verified locally).
  4	// Written with node: APIs so it runs on Node 24 today and stays Bun-compatible.
  5	
  6	import { spawn } from "node:child_process";
  7	
  8	// Agents can think for minutes; cap wall-clock. 10m: a repo-grounded run showed
  9	// 5m is too tight for larger evidence-gathering turns.
 10	export const DEFAULT_TIMEOUT_MS = 10 * 60 * 1000;
 11	
 12	export type CliCapture = { code: number | null; stdout: string; stderr: string; timedOut: boolean };
 13	
 14	// After SIGTERM-ing a timed-out group, wait this long for a graceful exit, then
 15	// SIGKILL the whole group. A CLI that traps/ignores SIGTERM cannot outlive this.
 16	export const KILL_GRACE_MS = 2_000;
 17	
 18	// Spawn a CLI in `cwd`. stdin is IGNORED (= </dev/null): the canary showed Codex
 19	// hangs waiting for stdin EOF otherwise. stdout/stderr captured separately.
 20	//
 21	// `detached: true` makes the child its OWN process-group leader (pgid === pid) so
 22	// a timeout can kill the WHOLE tree, not just the direct child. This is a
 23	// correctness fix, not hygiene: in the 2026-06-12 I Love Coding run a turn ran
 24	// past the cap, SIGTERM hit only the direct child, and a leaked worker kept the
 25	// stdout pipe open — so `close` never fired and the whole debate hung ~45 min at
 26	// ~0 CPU. Group-kill closes the pipe, `close` fires, the turn resolves as timeout,
 27	// and the round proceeds. (Negative pid in process.kill = signal the group.)
 28	function runCli(cmd: string, args: string[], cwd: string, timeoutMs: number): Promise<CliCapture> {
 29	  return new Promise((resolve) => {
 30	    const child = spawn(cmd, args, { cwd, stdio: ["ignore", "pipe", "pipe"], detached: true });
 31	    let stdout = "";
 32	    let stderr = "";
 33	    let timedOut = false;
 34	    let hardTimer: ReturnType<typeof setTimeout> | undefined;
 35	
 36	    // Signal the child's whole process group. ESRCH (group already gone) is benign.
 37	    // We target the group (-pid), never node's own group, because `detached` put
 38	    // the child in its own group — so this can't kill the orchestrator.
 39	    const killGroup = (signal: NodeJS.Signals) => {
 40	      try { if (child.pid) process.kill(-child.pid, signal); }
 41	      catch { /* already dead */ }
 42	    };
 43	
 44	    const timer = setTimeout(() => {
 45	      timedOut = true;
 46	      killGroup("SIGTERM");
 47	      hardTimer = setTimeout(() => killGroup("SIGKILL"), KILL_GRACE_MS); // escalate if ignored
 48	    }, timeoutMs);
 49	
 50	    const finish = (cap: CliCapture) => {
 51	      clearTimeout(timer);
 52	      if (hardTimer) clearTimeout(hardTimer);
 53	      resolve(cap);
 54	    };
 55	
 56	    child.stdout.on("data", (d) => { stdout += d.toString(); });
 57	    child.stderr.on("data", (d) => { stderr += d.toString(); });
 58	    child.on("error", (e) => { finish({ code: null, stdout, stderr: String(e), timedOut }); });
 59	    child.on("close", (code) => { finish({ code, stdout, stderr, timedOut }); });
 60	  });
 61	}
 62	
 63	export type AgentResult =
 64	  | { ok: true; text: string; costUsd?: number; raw?: CliCapture }
 65	  | { ok: false; error: string; budgetExhausted?: true; raw?: CliCapture };
 66	
 67	export type Participant = {
 68	  id: string;
 69	  display: string;
 70	  vendor: string; // used for the cross-vendor sanity check (diversity is the whole point)
 71	  run: (prompt: string, cwd: string) => Promise<AgentResult>;
 72	};
 73	
 74	// exit 126/127 = the shell could not run the binary at all (e.g. a stale asdf
 75	// shim shadowing the real install) — a setup problem, not an agent failure.
 76	function spawnFailure(r: CliCapture): string | null {
 77	  if (r.code === 126 || r.code === 127) {
 78	    return `binary not runnable (exit ${r.code}) — check PATH / asdf shims, or set 'bin' in debate.yaml. stderr: ${r.stderr.slice(0, 200)}`;
 79	  }
 80	  return null;
 81	}
 82	
 83	// --- Claude Code: rich JSON envelope -------------------------------------------------
 84	export type ClaudeOpts = { maxBudgetUsd?: number; timeoutMs?: number; effort?: string };
 85	
 86	export function claudeAdapter(model = "sonnet", opts: ClaudeOpts = {}): Participant {
 87	  // $5 default: raised from $2 after the redactio (full transcript + repo traversal at
 88	  // effort:high) hit the $2 cap on a real medium-sized run. Use --budget to override.
 89	  const budget = opts.maxBudgetUsd ?? 5;
 90	  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
 91	  return {
 92	    id: "claude",
 93	    display: `Claude (${model})`,
 94	    vendor: "anthropic",
 95	    async run(prompt, cwd) {
 96	      const r = await runCli("claude", [
 97	        "-p", prompt,
 98	        "--output-format", "json",
 99	        "--model", model,
100	        // read-only evidence tools; enough to run the existing tests = the moat.
101	        // Comma-separated permission rules (research/claude-code-headless.md) —
102	        // the rules themselves contain spaces, so commas are the only safe separator.
103	        "--allowedTools", "Read,Glob,Grep,WebFetch,WebSearch,Bash(npm test *),Bash(pytest *),Bash(bun test *),Bash(rspec *),Bash(bundle exec rspec *),Bash(ls *),Bash(cat *),Bash(git diff *),Bash(git log *)",
104	        "--disallowedTools", "Edit,Write,NotebookEdit",
105	        "--permission-mode", "dontAsk", // headless: deny anything not allowlisted, never prompt
106	        "--no-session-persistence",
107	        "--max-budget-usd", String(budget),
108	        // Reasoning effort, to dose token spend. Native flag; values: low|medium|high|xhigh|max.
109	        ...(opts.effort ? ["--effort", opts.effort] : []),
110	      ], cwd, timeoutMs);
111	      if (r.timedOut) return { ok: false, error: "timeout", raw: r };
112	      const spawnErr = spawnFailure(r);
113	      if (spawnErr) return { ok: false, error: spawnErr, raw: r };
114	      try {
115	        const j = JSON.parse(r.stdout);
116	        // CANARY LESSON: trust is_error, NOT subtype. On error, subtype stays "success"
117	        // while is_error flips true. So classify on is_error + exit code.
118	        if (r.code === 0 && j.is_error === false) {
119	          return { ok: true, text: String(j.result ?? ""), costUsd: j.total_cost_usd, raw: r };
120	        }
121	        // CANARY LESSON (2026-06-11): on budget exhaustion there is NO `result`
122	        // string — the message lives in the `errors` array and subtype becomes
123	        // "error_max_budget_usd". Read all three places, most specific first.
124	        // Note: for SUCCESS we trust is_error not subtype (subtype lies); but for
125	        // budget exhaustion specifically, subtype IS the reliable discriminator.
126	        const budgetExhausted: true | undefined = j.subtype === "error_max_budget_usd" ? true : undefined;
127	        const error =
128	          Array.isArray(j.errors) && j.errors.length > 0 ? j.errors.join("; ")
129	          : typeof j.result === "string" && j.result ? j.result
130	          : `is_error=${j.is_error} subtype=${j.subtype}`;
131	        return { ok: false, error, ...(budgetExhausted && { budgetExhausted }), raw: r };
132	      } catch {
133	        return { ok: false, error: `exit=${r.code} ${r.stderr.slice(0, 200)}`, raw: r };
134	      }
135	    },
136	  };
137	}
138	
139	// --- Antigravity (Gemini): text-only -------------------------------------------------
140	export type AgyOpts = { timeoutMs?: number };
141	
142	export function agyAdapter(model = "Gemini 3.5 Flash (High)", opts: AgyOpts = {}): Participant {
143	  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
144	  return {
145	    id: "agy",
146	    display: `Antigravity (${model})`,
147	    vendor: "google",
148	    async run(prompt, cwd) {
149	      // agy has NO --output-format/--json (canary): stdout IS the answer, clean.
150	      // --sandbox: print mode is agentic and can auto-execute terminal commands;
151	      // sandbox keeps it on terminal restrictions. Canaried 2026-06-11.
152	      const r = await runCli("agy", [
153	        "--sandbox",
154	        "--print-timeout", `${Math.ceil(timeoutMs / 60_000)}m`, // agy's own default (5m) is shorter than ours
155	        "--model", model,
156	        "-p", prompt,
157	      ], cwd, timeoutMs);
158	      if (r.timedOut) return { ok: false, error: "timeout", raw: r };
159	      const spawnErr = spawnFailure(r);
160	      if (spawnErr) return { ok: false, error: spawnErr, raw: r };
161	      const text = r.stdout.trim();
162	      if (r.code === 0 && text.length > 0) return { ok: true, text, raw: r };
163	      return { ok: false, error: `exit=${r.code} ${r.stderr.slice(0, 200)}`, raw: r };
164	    },
165	  };
166	}
167	
168	// --- Codex (OpenAI): JSONL stream ----------------------------------------------------
169	export type CodexOpts = { bin?: string; timeoutMs?: number; effort?: string };
170	
171	export function codexAdapter(model?: string, opts: CodexOpts = {}): Participant {
172	  // `bin` is configurable because a stale shim can shadow the real binary
173	  // (observed locally: asdf shim with codex 0.1.x hiding Homebrew's 0.139.0).
174	  const bin = opts.bin ?? "codex";
175	  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
176	  return {
177	    id: "codex",
178	    display: `Codex (${model ?? "account default"})`,
179	    vendor: "openai",
180	    async run(prompt, cwd) {
181	      // Recipe canaried on codex 0.139.0 (2026-06-11) + research/codex-cli-headless.md:
182	      // -s read-only is an OS-enforced sandbox; --ephemeral = no session rollout
183	      // files (orchestrator owns memory); --skip-git-repo-check for temp dirs.
184	      const r = await runCli(bin, [
185	        "exec",
186	        "--json",
187	        "-s", "read-only",
188	        "--skip-git-repo-check",
189	        "--ephemeral",
190	        ...(model ? ["-m", model] : []),
191	        // Reasoning effort, to dose token spend. No dedicated flag: set it via a
192	        // config override. Values: minimal|low|medium|high.
193	        ...(opts.effort ? ["-c", `model_reasoning_effort="${opts.effort}"`] : []),
194	        prompt,
195	      ], cwd, timeoutMs);
196	      if (r.timedOut) return { ok: false, error: "timeout", raw: r };
197	      const spawnErr = spawnFailure(r);
198	      if (spawnErr) return { ok: false, error: spawnErr, raw: r };
199	      // JSONL: final answer = LAST item.completed with item.type === "agent_message".
200	      // Success = exit 0 && a turn.completed seen && no error/turn.failed event.
201	      let text = "";
202	      let turnCompleted = false;
203	      let failure = "";
204	      for (const line of r.stdout.split("\n")) {
205	        if (!line.trim()) continue;
206	        let ev: any;
207	        try { ev = JSON.parse(line); } catch { continue; } // tolerate non-JSON noise on stdout
208	        if (ev.type === "item.completed" && ev.item?.type === "agent_message") text = String(ev.item.text ?? "");
209	        else if (ev.type === "turn.completed") turnCompleted = true;
210	        else if (ev.type === "turn.failed") failure ||= String(ev.error?.message ?? "turn.failed");
211	        else if (ev.type === "error") failure ||= String(ev.message ?? "error event");
212	      }
213	      if (r.code === 0 && turnCompleted && !failure && text.length > 0) {
214	        return { ok: true, text, raw: r }; // no costUsd: ChatGPT-account auth reports tokens, not dollars
215	      }
216	      return { ok: false, error: failure || `exit=${r.code} ${r.stderr.slice(0, 200)}`, raw: r };
217	    },
218	  };
219	}
220	
221	// --- Pi (earendil-works/pi): JSON event stream, multi-LLM harness --------------------
222	// `pi` is a minimal, low-overhead coding agent that fronts MANY providers behind one
223	// harness (https://github.com/earendil-works/pi). The *harness* is its own vendor here:
224	// the cross-vendor diversity check keys on the harness, not the backing model.
225	export type PiOpts = { bin?: string; timeoutMs?: number; effort?: string };
226	
227	export function piAdapter(model?: string, opts: PiOpts = {}): Participant {
228	  // `bin` is configurable for the same reason as codex: a stale shim can shadow it.
229	  const bin = opts.bin ?? "pi";
230	  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
231	  return {
232	    id: "pi",
233	    display: `Pi (${model ?? "account default"})`,
234	    vendor: "pi",
235	    async run(prompt, cwd) {
236	      // `--mode json` emits the session as JSON lines on stdout (docs: pi.dev/docs/latest/json).
237	      // `--no-session` = ephemeral, the orchestrator owns memory. READ-ONLY evidence: pi has
238	      // no OS sandbox, so we restrict the tool ALLOWLIST to read,grep,find,ls (omitting bash,
239	      // edit, write) — agents can inspect the repo but never mutate it. `--thinking` doses
240	      // reasoning effort (off|minimal|low|medium|high|xhigh). Prompt is the positional.
241	      const r = await runCli(bin, [
242	        "--mode", "json",
243	        "--no-session",
244	        "--tools", "read,grep,find,ls",
245	        ...(model ? ["--model", model] : []),
246	        ...(opts.effort ? ["--thinking", opts.effort] : []),
247	        prompt,
248	      ], cwd, timeoutMs);
249	      if (r.timedOut) return { ok: false, error: "timeout", raw: r };
250	      const spawnErr = spawnFailure(r);
251	      if (spawnErr) return { ok: false, error: spawnErr, raw: r };
252	      // JSON lines: final answer = the LAST `message_end` for an assistant message; its
253	      // `message.content` is either a string or an array of blocks (take the `text` ones).
254	      // Failures surface in `auto_retry_end.finalError`. Success = exit 0 + a final message.
255	      let text = "";
256	      let failure = "";
257	      for (const line of r.stdout.split("\n")) {
258	        if (!line.trim()) continue;
259	        let ev: any;
260	        try { ev = JSON.parse(line); } catch { continue; } // tolerate non-JSON noise on stdout
261	        if (ev.type === "message_end" && ev.message?.role === "assistant") {
262	          text = piMessageText(ev.message);
263	        } else if (ev.type === "auto_retry_end" && ev.finalError) {
264	          failure ||= String(ev.finalError);
265	        }
266	      }
267	      if (r.code === 0 && !failure && text.length > 0) return { ok: true, text, raw: r };
268	      return { ok: false, error: failure || `exit=${r.code} ${r.stderr.slice(0, 200)}`, raw: r };
269	    },
270	  };
271	}
272	
273	// Pi's assistant message content is a string OR an array of content blocks; join the
274	// text blocks. Kept tiny and defensive so a shape tweak degrades to "" not a throw.
275	function piMessageText(message: any): string {
276	  const c = message?.content;
277	  if (typeof c === "string") return c.trim();
278	  if (Array.isArray(c)) {
279	    return c.map((b) => (typeof b === "string" ? b : typeof b?.text === "string" ? b.text : "")).join("").trim();
280	  }
281	  return "";
282	}
283	
284	// --- GitHub Copilot CLI: JSONL stream ------------------------------------------------
285	export type CopilotCliOpts = { bin?: string; timeoutMs?: number; effort?: string };
286	
287	export function copilotCliAdapter(model?: string, opts: CopilotCliOpts = {}): Participant {
288	  // The npm package is @github/copilot, but the installed binary is `copilot`.
289	  // Keep `bin` configurable to handle shadowed/stale shims like codex/pi.
290	  const bin = opts.bin ?? "copilot";
291	  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
292	  return {
293	    id: "copilot-cli",
294	    display: `Copilot CLI (${model ?? "auto"})`,
295	    vendor: "github-copilot",
296	    async run(prompt, cwd) {
297	      // Canaried with @github/copilot 1.0.65: `-p` is non-interactive prompt mode;
298	      // `--output-format json` is JSONL; read-only evidence is a tool availability
299	      // allowlist of view/glob/grep, with builtin GitHub MCP disabled.
300	      const r = await runCli(bin, [
301	        "-p", prompt,
302	        "--output-format", "json",
303	        "--stream", "off",
304	        "--no-color",
305	        "--no-remote",
306	        "--no-remote-export",
307	        "--no-auto-update",
308	        "--no-ask-user",
309	        "--disable-builtin-mcps",
310	        "--available-tools", "view,glob,grep",
311	        ...(model ? ["--model", model] : []),
312	        ...(opts.effort ? ["--effort", opts.effort] : []),
313	      ], cwd, timeoutMs);
314	      if (r.timedOut) return { ok: false, error: "timeout", raw: r };
315	      const spawnErr = spawnFailure(r);
316	      if (spawnErr) return { ok: false, error: spawnErr, raw: r };
317	
318	      let text = "";
319	      let sawResult = false;
320	      let resultExit: number | undefined;
321	      let failure = "";
322	      for (const line of r.stdout.split("\n")) {
323	        if (!line.trim()) continue;
324	        let ev: any;
325	        try { ev = JSON.parse(line); } catch { continue; }
326	        if (ev.type === "assistant.message" && typeof ev.data?.content === "string") {
327	          text = ev.data.content.trim();
328	        } else if (ev.type === "result") {
329	          sawResult = true;
330	          resultExit = typeof ev.exitCode === "number" ? ev.exitCode : undefined;
331	          if (ev.error) failure ||= String(ev.error);
332	        } else if (ev.type === "error") {
333	          failure ||= String(ev.message ?? ev.data?.message ?? "error event");
334	        }
335	      }
336	      if (r.code === 0 && sawResult && resultExit === 0 && !failure && text.length > 0) return { ok: true, text, raw: r };
337	      return { ok: false, error: failure || r.stderr.trim().slice(0, 200) || `exit=${r.code}`, raw: r };
338	    },
339	  };
340	}

