168	// --- Codex (OpenAI): JSONL stream ----------------------------------------------------
169	export type CodexOpts = { bin?: string; timeoutMs?: number; effort?: string };
170	
171	export function codexAdapter(model?: string, opts: CodexOpts = {}): Participant {
172	  // `bin` is configurable because a stale shim can shadow the real binary
173	  // (observed locally: asdf shim with codex 0.1.x hiding Homebrew's 0.139.0).
174	  const bin = opts.bin ?? "codex";
175	  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
176	  return {
177	    id: "codex",
178	    display: `Codex (${model ?? "account default"})`,
179	    vendor: "openai",
180	    async run(prompt, cwd) {
181	      // Recipe canaried on codex 0.139.0 (2026-06-11) + research/codex-cli-headless.md:
182	      // -s read-only is an OS-enforced sandbox; --ephemeral = no session rollout
183	      // files (orchestrator owns memory); --skip-git-repo-check for temp dirs.
184	      const r = await runCli(bin, [
185	        "exec",
186	        "--json",
187	        "-s", "read-only",
188	        "--skip-git-repo-check",
189	        "--ephemeral",
190	        ...(model ? ["-m", model] : []),
191	        // Reasoning effort, to dose token spend. No dedicated flag: set it via a
192	        // config override. Values: minimal|low|medium|high.
193	        ...(opts.effort ? ["-c", `model_reasoning_effort="${opts.effort}"`] : []),
194	        prompt,
195	      ], cwd, timeoutMs);
196	      if (r.timedOut) return { ok: false, error: "timeout", raw: r };
197	      const spawnErr = spawnFailure(r);
198	      if (spawnErr) return { ok: false, error: spawnErr, raw: r };
199	      // JSONL: final answer = LAST item.completed with item.type === "agent_message".
200	      // Success = exit 0 && a turn.completed seen && no error/turn.failed event.
201	      let text = "";
202	      let turnCompleted = false;
203	      let failure = "";
204	      for (const line of r.stdout.split("\n")) {
205	        if (!line.trim()) continue;
206	        let ev: any;
207	        try { ev = JSON.parse(line); } catch { continue; } // tolerate non-JSON noise on stdout
208	        if (ev.type === "item.completed" && ev.item?.type === "agent_message") text = String(ev.item.text ?? "");
209	        else if (ev.type === "turn.completed") turnCompleted = true;
210	        else if (ev.type === "turn.failed") failure ||= String(ev.error?.message ?? "turn.failed");
211	        else if (ev.type === "error") failure ||= String(ev.message ?? "error event");
212	      }
213	      if (r.code === 0 && turnCompleted && !failure && text.length > 0) {
214	        return { ok: true, text, raw: r }; // no costUsd: ChatGPT-account auth reports tokens, not dollars
215	      }
216	      return { ok: false, error: failure || `exit=${r.code} ${r.stderr.slice(0, 200)}`, raw: r };
217	    },
218	  };
219	}
