221	// --- Pi (earendil-works/pi): JSON event stream, multi-LLM harness --------------------
222	// `pi` is a minimal, low-overhead coding agent that fronts MANY providers behind one
223	// harness (https://github.com/earendil-works/pi). The *harness* is its own vendor here:
224	// the cross-vendor diversity check keys on the harness, not the backing model.
225	export type PiOpts = { bin?: string; timeoutMs?: number; effort?: string };
226	
227	export function piAdapter(model?: string, opts: PiOpts = {}): Participant {
228	  // `bin` is configurable for the same reason as codex: a stale shim can shadow it.
229	  const bin = opts.bin ?? "pi";
230	  const timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
231	  return {
232	    id: "pi",
233	    display: `Pi (${model ?? "account default"})`,
234	    vendor: "pi",
235	    async run(prompt, cwd) {
236	      // `--mode json` emits the session as JSON lines on stdout (docs: pi.dev/docs/latest/json).
237	      // `--no-session` = ephemeral, the orchestrator owns memory. READ-ONLY evidence: pi has
238	      // no OS sandbox, so we restrict the tool ALLOWLIST to read,grep,find,ls (omitting bash,
239	      // edit, write) — agents can inspect the repo but never mutate it. `--thinking` doses
240	      // reasoning effort (off|minimal|low|medium|high|xhigh). Prompt is the positional.
241	      const r = await runCli(bin, [
242	        "--mode", "json",
243	        "--no-session",
244	        "--tools", "read,grep,find,ls",
245	        ...(model ? ["--model", model] : []),
246	        ...(opts.effort ? ["--thinking", opts.effort] : []),
247	        prompt,
248	      ], cwd, timeoutMs);
249	      if (r.timedOut) return { ok: false, error: "timeout", raw: r };
250	      const spawnErr = spawnFailure(r);
251	      if (spawnErr) return { ok: false, error: spawnErr, raw: r };
252	      // JSON lines: final answer = the LAST `message_end` for an assistant message; its
253	      // `message.content` is either a string or an array of blocks (take the `text` ones).
254	      // Failures surface in `auto_retry_end.finalError`. Success = exit 0 + a final message.
255	      let text = "";
256	      let failure = "";
257	      for (const line of r.stdout.split("\n")) {
258	        if (!line.trim()) continue;
259	        let ev: any;
260	        try { ev = JSON.parse(line); } catch { continue; } // tolerate non-JSON noise on stdout
261	        if (ev.type === "message_end" && ev.message?.role === "assistant") {
262	          text = piMessageText(ev.message);
263	        } else if (ev.type === "auto_retry_end" && ev.finalError) {
264	          failure ||= String(ev.finalError);
265	        }
266	      }
267	      if (r.code === 0 && !failure && text.length > 0) return { ok: true, text, raw: r };
268	      return { ok: false, error: failure || `exit=${r.code} ${r.stderr.slice(0, 200)}`, raw: r };
269	    },
270	  };
271	}
272	
273	// Pi's assistant message content is a string OR an array of content blocks; join the
274	// text blocks. Kept tiny and defensive so a shape tweak degrades to "" not a throw.
275	function piMessageText(message: any): string {
276	  const c = message?.content;
277	  if (typeof c === "string") return c.trim();
278	  if (Array.isArray(c)) {
279	    return c.map((b) => (typeof b === "string" ? b : typeof b?.text === "string" ? b.text : "")).join("").trim();
280	  }
281	  return "";
282	}
