  1	// Install / setup phase (Kaizen). Two jobs, both about making Disputatio portable
  2	// across the two ways it runs — from source (`node src/index.ts`) and as the installed
  3	// binary (`npm install -g disputatio` → `disputatio`):
  4	//
  5	//   1. resolveConfigText — the runtime config lookup. ONE canonical user config,
  6	//      `~/.config/disputatio/config.yaml`, read identically in both modes. The shipped
  7	//      `examples/debate.yaml` is a copy-me TEMPLATE, never auto-loaded (that coupling was
  8	//      the P2 footgun: its host-specific `bin:` broke no-config runs on other machines).
  9	//
 10	//   2. runInit (`disputatio --init`) — probe the lineup, resolve each CLI's real binary
 11	//      (the stale-asdf-shim dance), and WRITE that user config. Explicit command, not an
 12	//      npm postinstall hook: it canaries, so it needs the CLIs authenticated first.
 13	
 14	import { readFile, writeFile, copyFile, mkdir, access } from "node:fs/promises";
 15	import { homedir } from "node:os";
 16	import { join, dirname } from "node:path";
 17	import { execFile } from "node:child_process";
 18	import { promisify } from "node:util";
 19	import { runIsolated } from "./debate.ts";
 20	import { CANARY_PROMPT, CANARY_TIMEOUT_MS } from "./doctor.ts";
 21	import { parseDebateConfig, serializeDebateConfig, type ParticipantSpec, type DebateConfig } from "./config.ts";
 22	import type { Participant } from "./adapters.ts";
 23	
 24	const execFileAsync = promisify(execFile);
 25	
 26	// XDG-aware canonical config home. Both run modes read/write the SAME file, so the
 27	// installed binary and a source checkout never disagree on which config is live.
 28	export function userConfigPath(env: NodeJS.ProcessEnv = process.env): string {
 29	  const base = env.XDG_CONFIG_HOME?.trim() || join(homedir(), ".config");
 30	  return join(base, "disputatio", "config.yaml");
 31	}
 32	
 33	// Runtime config resolution, in precedence order:
 34	//   1. explicit --config <path>  → read it; a missing file HARD-FAILS (caller's choice).
 35	//   2. ~/.config/disputatio/config.yaml exists → read it.
 36	//   3. neither → text:null, meaning "use the built-in lineup" (claude + codex, no judge).
 37	// ENOENT on step 2 is the only swallowed error: a malformed/unreadable user config still
 38	// surfaces (parse throws downstream, or a non-ENOENT fs error rethrows here).
 39	export async function resolveConfigText(
 40	  configArg: string | undefined,
 41	  env: NodeJS.ProcessEnv = process.env,
 42	): Promise<{ text: string | null; source: string }> {
 43	  if (configArg) return { text: await readFile(configArg, "utf8"), source: configArg };
 44	  const userPath = userConfigPath(env);
 45	  try {
 46	    return { text: await readFile(userPath, "utf8"), source: userPath };
 47	  } catch (e) {
 48	    if ((e as NodeJS.ErrnoException).code !== "ENOENT") throw e;
 49	    return { text: null, source: "built-in lineup (no config)" };
 50	  }
 51	}
 52	
 53	// --- binary resolution ---------------------------------------------------------------
 54	
 55	export type BinResolution = { ok: boolean; bin?: string; tried: string[] };
 56	
 57	// Find the binary that actually works. Try `defaultBin` (PATH) first; if its canary
 58	// fails, try each alternative in order. PIN (return `bin`) ONLY when a non-default
 59	// candidate is the one that worked — a working PATH binary needs no override, so the
 60	// generated config stays minimal and as portable as the machine allows. The canary is
 61	// the full adapter round-trip, not `--version`: the codex 0.1.x stale shim is runnable
 62	// and reports its version, but the repo is version-agnostic by design, so the only
 63	// honest test of "is this the right binary" is whether it answers the real canary.
 64	export async function resolveBinary(
 65	  defaultBin: string,
 66	  alternatives: string[],
 67	  canary: (bin: string) => Promise<boolean>,
 68	): Promise<BinResolution> {
 69	  const tried = [defaultBin];
 70	  if (await canary(defaultBin)) return { ok: true, tried };
 71	  for (const alt of alternatives) {
 72	    if (alt === defaultBin) continue;
 73	    tried.push(alt);
 74	    if (await canary(alt)) return { ok: true, bin: alt, tried };
 75	  }
 76	  return { ok: false, tried };
 77	}
 78	
 79	// Candidate binaries to fall back to when the PATH one fails: everything `which -a`
 80	// knows about, plus the usual Homebrew/local locations (where the real codex hides
 81	// behind a stale asdf shim on this machine). Best-effort: a missing `which` or dir
 82	// just yields fewer candidates.
 83	const KNOWN_BIN_DIRS = ["/opt/homebrew/bin", "/usr/local/bin", "/usr/bin"];
 84	export async function findAlternatives(bin: string): Promise<string[]> {
 85	  const found: string[] = [];
 86	  try {
 87	    const { stdout } = await execFileAsync("which", ["-a", bin]);
 88	    for (const line of stdout.split("\n")) { const p = line.trim(); if (p) found.push(p); }
 89	  } catch { /* `which` absent or no match — fall through to known dirs */ }
 90	  for (const dir of KNOWN_BIN_DIRS) {
 91	    const p = join(dir, bin);
 92	    try { await access(p); found.push(p); } catch { /* not here */ }
 93	  }
 94	  return [...new Set(found)];
 95	}
 96	
 97	// --- init orchestration --------------------------------------------------------------
 98	
 99	// Adapters that honor a `bin:` override can be repointed when a stale shim shadows
100	// the real install; other adapters can canary PATH but cannot be repointed.
101	const BIN_OVERRIDABLE = new Set<string>(["codex", "pi", "copilot-cli"]);
102	const DEFAULT_BIN = new Map<string, string>([["copilot-cli", "copilot"]]);
103	
104	export type InitDeps = {
105	  // Inject the lineup factory (it lives in index.ts, the composition root) so install.ts
106	  // doesn't import index.ts. Tests pass a factory returning stub participants.
107	  buildParticipant: (spec: ParticipantSpec, timeoutMs: number) => Participant;
108	  canary?: (p: Participant) => Promise<boolean>;
109	  findAlternatives?: (bin: string) => Promise<string[]>;
110	};
111	
112	const defaultCanary = async (p: Participant): Promise<boolean> => (await runIsolated(p, CANARY_PROMPT)).ok;
113	
114	export type InitResult = { exitCode: number; configPath: string; serialized: string; report: string };
115	
116	// Probe each participant, resolve its working binary, seed the judge, and write the
117	// user config. Returns the artifact + a human report; exit 1 if any participant has no
118	// working binary (doctor remains the auth/health gate, but a lineup with a dead CLI
119	// should not be written as "ready").
120	export async function runInit(
121	  specs: ParticipantSpec[],
122	  judge: ParticipantSpec | undefined,
123	  configPath: string,
124	  opts: { force?: boolean; deps: InitDeps },
125	): Promise<InitResult> {
126	  const canary = opts.deps.canary ?? defaultCanary;
127	  const findAlts = opts.deps.findAlternatives ?? findAlternatives;
128	  const build = opts.deps.buildParticipant;
129	
130	  const lines: string[] = [];
131	  const resolved: ParticipantSpec[] = [];
132	  let allOk = true;
133	
134	  for (const spec of specs) {
135	    const overridable = BIN_OVERRIDABLE.has(spec.adapter);
136	    const defaultBin = spec.bin ?? DEFAULT_BIN.get(spec.adapter) ?? spec.adapter;
137	    const probe = (bin: string) => canary(build({ ...spec, bin }, CANARY_TIMEOUT_MS));
138	    const alts = overridable ? await findAlts(defaultBin) : [];
139	    const res = await resolveBinary(defaultBin, alts, probe);
140	
141	    // Pin an auto-detected alt; otherwise preserve any bin the caller already set.
142	    const out: ParticipantSpec = { ...spec };
143	    const pinned = res.bin ?? spec.bin;
144	    if (pinned) out.bin = pinned; else delete out.bin;
145	    resolved.push(out);
146	
147	    if (!res.ok) {
148	      allOk = false;
149	      lines.push(`  ✗ ${spec.adapter}: no working binary (tried ${res.tried.join(", ")})`);
150	    } else if (res.bin) {
151	      lines.push(`  ✓ ${spec.adapter}: pinned bin ${res.bin} (PATH binary failed)`);
152	    } else {
153	      lines.push(`  ✓ ${spec.adapter}: ${defaultBin} (on PATH)`);
154	    }
155	  }
156	
157	  const cfg: DebateConfig = { participants: resolved };
158	  if (judge) cfg.judge = judge;
159	  const serialized = serializeDebateConfig(cfg);
160	
161	  if (allOk) {
162	    await mkdir(dirname(configPath), { recursive: true });
163	    // Never clobber silently: back up an existing config unless --force.
164	    if (!opts.force) {
165	      try { await access(configPath); await copyFile(configPath, `${configPath}.bak`); lines.push(`  backed up existing config → ${configPath}.bak`); }
166	      catch { /* nothing to back up */ }
167	    }
168	    await writeFile(configPath, serialized, "utf8");
169	    lines.push(`  wrote ${configPath}${judge ? " (judge seeded)" : ""}`);
170	  } else {
171	    lines.push(`  not written — authenticate the failing CLI(s) and re-run`);
172	  }
173	
174	  const report = [`disputatio init — ${specs.length} participant(s)`, ...lines].join("\n");
175	  return { exitCode: allOk ? 0 : 1, configPath, serialized, report };
176	}
