  1	// Quaestio input resolution — where the question under debate comes from. Pure (no fs)
  2	// so it is unit-testable: index.ts does the actual readFile. The quaestio is given
  3	// INLINE by default (the sole positional IS the question); --file <path> reads it from a
  4	// markdown file instead. rounds/repo are named flags (--rounds/--repo), NOT positionals,
  5	// so the quaestio source is the only thing to disambiguate here — no positional juggling.
  6	
  7	export type QuaestioInput =
  8	  | { ok: true; source: "file"; path: string }
  9	  | { ok: true; source: "inline"; text: string }
 10	  | { ok: false; error: string };
 11	
 12	export function resolveQuaestioInput(
 13	  filePath: string | undefined,
 14	  positionals: string[],
 15	): QuaestioInput {
 16	  if (filePath !== undefined) {
 17	    if (positionals.length > 0)
 18	      return { ok: false, error: "pass the quaestio inline OR with --file, not both" };
 19	    return { ok: true, source: "file", path: filePath };
 20	  }
 21	  if (positionals.length === 0) return { ok: false, error: "no quaestio given" };
 22	  if (positionals.length > 1)
 23	    return {
 24	      ok: false,
 25	      error: `unexpected extra arguments — did you forget to quote the quaestio? (${positionals.join(" ")})`,
 26	    };
 27	  return { ok: true, source: "inline", text: positionals[0] };
 28	}
